bool openref_rt595_audio_io_mcux_init(openref_rt595_audio_io_mcux_t*a,const openref_rt595_audio_io_mcux_config_t*c){if(!a||!c||!c->dmic||!c->i2s||!c->dma||c->dmic_dma_channel==c->i2s_dma_channel)return false;a->config=*c;DMA_EnableChannel(c->dma,c->dmic_dma_channel);DMA_EnableChannel(c->dma,c->i2s_dma_channel);DMA_CreateHandle(&a->dmic_dma,c->dma,c->dmic_dma_channel);DMA_CreateHandle(&a->i2s_dma,c->dma,c->i2s_dma_channel);if(DMIC_TransferCreateHandleDMA(c->dmic,&a->dmic_handle,capture_done,a,&a->dmic_dma)!=kStatus_Success)return false;I2S_TxTransferCreateHandleDMA(c->i2s,&a->i2s_handle,&a->i2s_dma,playout_done,a);openref_rt595_audio_io_ops_t o={.capture=capture,.playout=playout,.abort=abort_io,.enter_critical=enter_critical,.exit_critical=exit_critical,.context=a};return openref_rt595_audio_io_init(&a->io,&o);}
